// Order-24 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same function as the direct form.
module iir24_v2 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] r19;
  reg [15:0] r20;
  reg [15:0] r21;
  reg [15:0] r22;
  reg [15:0] r23;
  reg [15:0] r24;
  reg [15:0] y2;
  always @(posedge clk) begin
    if (!rst_n) begin y <= 16'd0; y2 <= 16'd0; r1 <= 16'd0; r2 <= 16'd0; r3 <= 16'd0; r4 <= 16'd0; r5 <= 16'd0; r6 <= 16'd0; r7 <= 16'd0; r8 <= 16'd0; r9 <= 16'd0; r10 <= 16'd0; r11 <= 16'd0; r12 <= 16'd0; r13 <= 16'd0; r14 <= 16'd0; r15 <= 16'd0; r16 <= 16'd0; r17 <= 16'd0; r18 <= 16'd0; r19 <= 16'd0; r20 <= 16'd0; r21 <= 16'd0; r22 <= 16'd0; r23 <= 16'd0; r24 <= 16'd0; end
    else begin
      y <= ((63*x) + r1) & 16'hFFFF;
      r2 <= ((15*x) + r2) & 16'hFFFF;
      r3 <= ((4*x) + r3) & 16'hFFFF;
      r4 <= ((35*x) + r4) & 16'hFFFF;
      r5 <= ((41*x) + r5) & 16'hFFFF;
      r6 <= ((47*x) + r6) & 16'hFFFF;
      r7 <= ((40*x) + r7) & 16'hFFFF;
      r8 <= ((2*x) + r8) & 16'hFFFF;
      r9 <= ((60*x) + r9) & 16'hFFFF;
      r10 <= ((19*x) + r10) & 16'hFFFF;
      r11 <= ((5*x) + r11) & 16'hFFFF;
      r12 <= ((12*x) + r12) & 16'hFFFF;
      r13 <= ((50*x) + r13) & 16'hFFFF;
      r14 <= ((28*x) + r14) & 16'hFFFF;
      r15 <= ((46*x) + r15) & 16'hFFFF;
      r16 <= ((49*x) + r16) & 16'hFFFF;
      r17 <= ((15*x) + r17) & 16'hFFFF;
      r18 <= ((22*x) + r18) & 16'hFFFF;
      r19 <= ((36*x) + r19) & 16'hFFFF;
      r20 <= ((52*x) + r20) & 16'hFFFF;
      r21 <= ((8*x) + r21) & 16'hFFFF;
      r22 <= ((31*x) + r22) & 16'hFFFF;
      r23 <= ((50*x) + r23) & 16'hFFFF;
      r24 <= ((57*x) + r24) & 16'hFFFF;
      y2 <= ((9*y)>>4 | ((5*y2)>>4)) & 16'hFFFF;
    end
  end
endmodule fsm
(
    input logic clk,
    input logic reset,
    input logic [7:0] din,
    output reg [7:0] dout,
    output reg read_enable,
    output reg write_enable
);

    reg [3:0] state;
    reg [3:0] next_state;

    always @(*) begin
        case(state)
            4'd0: next_state = 4'd1;
            4'd1: next_state = 4'd2;
            4'd2: next_state = 4'd3;
            4'd3: next_state = 4'd4;
            4'd4: next_state = 4'd5;
            4'd5: next_state = 4'd6;
            4'd6: next_state = 4'd7;
            4'd7: next_state = 4'd6;
            default: next
